4733,517,'_mepr_custom_login_urls_default',''),(4734,517,'_mepr_custom_login_urls','a:0:{}'),(4735,517,'_mepr_expire_type','none'),(4736,517,'_mepr_expire_after','1'),(4737,517,'_mepr_expire_unit','days'),(4738,517,'_mepr_expire_fixed','2024-05-28'),(4739,517,'_mepr_tax_exempt',''),(4740,517,'_mepr_tax_class','standard'),(4741,517,'_mepr_allow_renewal',''),(4742,517,'_mepr_access_url',''),(4743,517,'_mepr_emails','a:1:{s:27:\"MeprUserProductWelcomeEmail\";a:4:{s:7:\"enabled\";b:1;s:12:\"use_template\";b:1;s:7:\"subject\";s:40:\"** Thanks for Purchasing {$product_name}\";s:4:\"body\";s:1612:\"<div id=\"header\" style=\"width: 680px;padding: 0px;margin: 0 auto;text-align: left\">\n<div id=\"header\" style=\"width: 680px;padding: 0px;margin: 0 auto;text-align: left\">\n<h1 style=\"font-size: 30px;margin-bottom: 4px\">Welcome to the Homemade Circus Toolkit, {$user_first_name}!</h1>\n</div>\n<div id=\"body\" style=\"width: 600px;background: white;padding: 40px;margin: 0 auto;text-align: left\">\n<div id=\"receipt\">\n<div class=\"section\" style=\"margin-bottom: 24px\">We can\'t wait for you to start learning our circus activities for care settings. But first things first, here\'s a reminder of how to login to your account:</div>\n<div class=\"section\" style=\"margin-bottom: 24px\">You can login here: <a href=\"http://homemade-circus.local/login\" target=\"_blank\" rel=\"noopener\">homemadecircus.co.uk/login</a></div>\n<div class=\"section\" style=\"margin-bottom: 24px\">Using the username and password you signed up with (a reminder of that below). Be sure to keep this email for future reference.</div>\n<div class=\"section\" style=\"margin-bottom: 24px\">\n<table class=\"transaction\" style=\"clear: both\">\n<tbody>\n<tr>\n<th style=\"text-align: left\">Username:</th>\n<td>{$username}</td>\n</tr>\n<tr>\n<th style=\"text-align: left\">Password:</th>\n<td>*** Password you set during signup ***</td>\n</tr>\n</tbody>\n</table>\n</div>\n<div class=\"section\" style=\"margin-bottom: 24px\">Once you\'re logged in you\'ll head straight to a welcome page that will give you a little more info on how to use the toolkit. Any questions just let us know,</div>\n<div class=\"section\" style=\"margin-bottom: 24px\">Cheers! The {$blog_name} Team</div>\n</div>\n</div>\n</div>\n\";}}'),(4744,517,'_mepr_disable_address_fields',''),(4745,517,'_mepr_allow_simultaneous_subscriptions',''),(4746,517,'_mepr_use_custom_template',''),(4747,517,'_mepr_custom_template','page-templates/page-template.php'),(4748,517,'_mepr_customize_payment_methods',''),(4749,517,'_mepr_customize_profile_fields','1'),(4750,517,'_mepr_cannot_purchase_message','You don\'t have access to purchase this item.'),(4751,517,'_mepr_plan_code',''),(4752,517,'_mepr_custom_profile_fields','a:4:{i:0;s:55:\"mepr_which_organisation_do_you_work_for_if_none_put_n_a\";i:1;s:32:\"mepr_where_did_you_hear_about_us\";i:2;s:51:\"mepr_what_are_you_planning_on_using_the_toolkit_for\";i:3;s:193:\"mepr_to_access_the_toolkit_for_free_we_just_ask_that_you_fill_a_short_feedback_form_that_we_will_email_you_2_weeks_after_you_sign_up_tick_the_box_to_agree_to_provide_feedback_on_your_experience\";}'),(4753,517,'_wp_page_template',''),(4754,517,'_meprmailchimptags_add_tag','1'),(4755,517,'_mepruserroles_enabled',''),(4756,517,'_mepruserroles_roles','a:0:{}'),(4757,517,'_yoast_wpseo_estimated-reading-time-minutes','0'),(4758,517,'_yoast_wpseo_wordproof_timestamp',''),(4759,517,'_meprmailchimptags_tag_id','5'),(4760,518,'_edit_lock','1775732130:3'),(4761,518,'_edit_last','3'),(4762,518,'_mepr_product_price','50.00'),(4763,518,'_mepr_product_period','1'),(4764,518,'_mepr_product_period_type','lifetime'),(4765,518,'_mepr_product_signup_button_text','Sign Up'),(4766,518,'_mepr_product_limit_cycles',''),(4767,518,'_mepr_product_limit_cycles_num','2'),(4768,518,'_mepr_product_limit_cycles_action','expire'),(4769,518,'_mepr_product_limit_cycles_expires_after','1'),(4770,518,'_mepr_product_limit_cycles_expires_type','day